<script setup>import AppShell from'../../Layouts/AppShell.vue';import GroupNav from'../../Components/GroupNav.vue';import PageHeader from'../../Components/PageHeader.vue';import UiAlert from'../../Components/UiAlert.vue';import UiButton from'../../Components/UiButton.vue';import{Head,Link,useForm}from'@inertiajs/vue3';const p=defineProps({group:Object,section:String,counts:Object});const form=useForm({...p.group}),tabs=[['general','General'],['privacy','Privacy'],['delivery','View & Download'],['branding','Branding'],['participants','Participants'],['folders','Folders'],['favorites','Client Favourites']];const save=()=>form.transform(data=>({...data,event_date:data.event_date?.slice?.(0,10)||data.event_date})).put(`/groups/${p.group.id}`);</script>
<template><AppShell><Head title="Group Settings"/><GroupNav :group="group"/><div class="lp-page mt-6"><PageHeader eyebrow="Group Settings" :title="group.name" description="Configure this Group without changing your account-level settings."/><div class="mt-6 grid gap-6 lg:grid-cols-[220px_1fr]"><nav class="lp-card h-fit p-2" aria-label="Group settings sections"><Link v-for="tab in tabs" :key="tab[0]" :href="`/groups/${group.id}/settings?section=${tab[0]}`" :class="['block rounded-xl px-4 py-3 text-sm font-semibold',section===tab[0]?'bg-indigo/10 text-indigo':'text-slate-600 hover:bg-slate-50']">{{tab[1]}}</Link></nav><UiCard><div v-if="section==='participants'"><h2 class="text-xl font-bold">Participants</h2><p class="lp-subtitle">{{counts.participants}} people currently belong to this Group.</p><UiButton :href="`/groups/${group.id}/members`" class="mt-6">Manage participants</UiButton></div><div v-else-if="section==='folders'"><h2 class="text-xl font-bold">Folders</h2><p class="lp-subtitle">{{counts.folders}} folders organize this Group’s gallery.</p><UiButton :href="`/groups/${group.id}/folders`" class="mt-6">Manage folders</UiButton></div><div v-else-if="section==='favorites'"><h2 class="text-xl font-bold">Client Favourites</h2><p class="lp-subtitle">{{counts.favorites}} accessible photographs have participant favourites.</p><UiButton :href="`/groups/${group.id}/favorites`" class="mt-6">View favourites</UiButton></div><form v-else class="space-y-5" @submit.prevent="save"><template v-if="section==='general'"><h2 class="text-xl font-bold">General</h2><label class="lp-label">Group name<input v-model="form.name" class="field mt-2" required><span v-if="form.errors.name" class="lp-error">{{form.errors.name}}</span></label><label class="lp-label">Description<textarea v-model="form.description" class="field mt-2 min-h-28"></textarea></label><div class="grid gap-4 md:grid-cols-2"><label class="lp-label">Project type<input v-model="form.event_type" class="field mt-2"></label><label class="lp-label">Project date<input v-model="form.event_date" type="date" class="field mt-2"></label><label class="lp-label">Location<input v-model="form.location" class="field mt-2"></label><label class="lp-label">Membership status<select v-model="form.membership_status" class="field mt-2"><option value="open">Open</option><option value="closed">Closed</option></select></label></div><label class="flex gap-3 text-sm"><input v-model="form.is_active" type="checkbox" class="accent-indigo">Group is active</label></template><template v-else-if="section==='privacy'"><h2 class="text-xl font-bold">Privacy</h2><label class="lp-label">Visibility<select v-model="form.privacy" class="field mt-2"><option value="private">Private</option><option value="link_only">Invitation only</option><option value="public">Public</option></select></label><label class="flex gap-3 text-sm"><input v-model="form.anyone_with_link_can_join" type="checkbox" class="accent-indigo">Allow joining through an authorized link</label><label class="flex gap-3 text-sm"><input v-model="form.allow_guest_upload" type="checkbox" class="accent-indigo">Allow participant uploads</label><label class="flex gap-3 text-sm"><input v-model="form.participants_can_edit_identity" type="checkbox" class="accent-indigo">Participants may edit their display identity</label><label class="flex gap-3 text-sm"><input v-model="form.face_recognition_enabled" type="checkbox" class="accent-indigo">Enable consent-led My Photos</label></template><template v-else-if="section==='delivery'"><h2 class="text-xl font-bold">View & Download</h2><label class="flex gap-3 text-sm"><input v-model="form.downloads_enabled" type="checkbox" class="accent-indigo">Allow authorized photo downloads</label><label class="flex gap-3 text-sm"><input v-model="form.watermark_enabled" type="checkbox" class="accent-indigo">Apply watermark to supported delivery variants</label></template><template v-else><h2 class="text-xl font-bold">Group branding</h2><p class="lp-subtitle">Only the currently supported Group watermark controls are shown. Studio logo and identity remain in Account Settings.</p><label class="flex gap-3 text-sm"><input v-model="form.watermark_enabled" type="checkbox" class="accent-indigo">Enable Group watermark</label><label class="lp-label">Watermark text<input v-model="form.watermark_text" class="field mt-2" maxlength="255"></label></template><UiAlert v-if="Object.keys(form.errors).length" tone="error">Review the highlighted Group settings.</UiAlert><UiButton type="submit" :loading="form.processing">Save Group Settings</UiButton></form></UiCard></div></div></AppShell></template>
